package com.example.praticum.ui.evaluation;
import android.view.*;import android.widget.TextView;import androidx.annotation.*;import androidx.recyclerview.widget.*;import com.example.praticum.R;import com.example.praticum.data.entity.EvaluationTeam;import java.util.*;import java.util.Locale;
public final class EvaluationTeamResultsAdapter extends RecyclerView.Adapter<EvaluationTeamResultsAdapter.Holder>{private final List<TeamItem> items=new ArrayList<>();private final Set<Long> closed=new HashSet<>();public void submitList(List<TeamItem>x,boolean expand){items.clear();if(x!=null)items.addAll(x);if(expand)closed.clear();notifyDataSetChanged();}
 @NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_evaluation_team_results,p,false));}
 public void onBindViewHolder(@NonNull Holder h,int p){TeamItem x=items.get(p);h.name.setText(x.team.getName());h.meta.setText(x.students.size()+(x.students.size()==1?" étudiant":" étudiants")+(x.evaluated?" · "+String.format(Locale.getDefault(),"%.2f / 20",x.score):" · Non évaluée"));boolean open=!closed.contains(x.team.getId());h.children.setVisibility(open?View.VISIBLE:View.GONE);h.chevron.setText(open?"⌃":"⌄");h.children.setLayoutManager(new LinearLayoutManager(h.itemView.getContext()));h.children.setNestedScrollingEnabled(false);EvaluationStudentAdapter a=new EvaluationStudentAdapter();h.children.setAdapter(a);a.submitList(x.students);h.header.setOnClickListener(v->{int n=h.getBindingAdapterPosition();if(n==RecyclerView.NO_POSITION)return;if(closed.contains(x.team.getId()))closed.remove(x.team.getId());else closed.add(x.team.getId());notifyItemChanged(n);});}public int getItemCount(){return items.size();}
 static final class TeamItem{final EvaluationTeam team;final List<EvaluationStudentAdapter.StudentEvaluationItem> students;final boolean evaluated;final double score;TeamItem(EvaluationTeam t,List<EvaluationStudentAdapter.StudentEvaluationItem>s,boolean e,double x){team=t;students=new ArrayList<>(s);evaluated=e;score=x;}}
 static final class Holder extends RecyclerView.ViewHolder{final View header;final TextView name,meta,chevron;final RecyclerView children;Holder(View v){super(v);header=v.findViewById(R.id.layoutEvaluationTeamHeader);name=v.findViewById(R.id.tvEvaluationTeamName);meta=v.findViewById(R.id.tvEvaluationTeamMeta);chevron=v.findViewById(R.id.tvEvaluationTeamChevron);children=v.findViewById(R.id.rvEvaluationTeamStudents);}}
}